17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Map;
24	import java.util.Objects;
25	import java.util.stream.Collectors;
26	
27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.CityOwnerLimitException;
39	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.security.core.Authentication;
51	import org.springframework.security.core.context.SecurityContextHolder;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Dedicated audit logger recording successful owner creations, including the authenticated
70	     * user and the new owner's id and membership number.
71	     */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /**
75	     * The maximum number of owners that may be registered on any single day (by registration date).
76	     * Once this many owners already carry today's registration date, further creation is rejected.
77	     */
78	    private static final int MAX_OWNERS_PER_DAY = 20;
79	
80	    /**
81	     * The maximum number of owners permitted in any single city. Once a city already contains
82	     * this many owners, creating a further owner in that city is rejected. Cities are matched
83	     * ignoring letter case.
84	     */
85	    private static final int MAX_OWNERS_PER_CITY = 8;
86	
87	    /**
88	     * The number of owners, counted from the very first ever created, that receive the
89	     * {@code FOUNDING} membership tier. Owners created once this many already exist receive
90	     * the {@code STANDARD} tier instead.
91	     */
92	    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;
93	
94	    private final ClinicService clinicService;
95	
96	    private final OwnerMapper ownerMapper;
97	
98	    private final PetMapper petMapper;
99	
100	    private final VisitMapper visitMapper;
101	
102	    public OwnerRestControllerV1(ClinicService clinicService,
103	                                 OwnerMapper ownerMapper,
104	                                 PetMapper petMapper,
105	                                 VisitMapper visitMapper) {
106	        this.clinicService = clinicService;
107	        this.ownerMapper = ownerMapper;
108	        this.petMapper = petMapper;
109	        this.visitMapper = visitMapper;
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
115	        Collection<Owner> owners;
116	        if (lastName != null) {
117	            owners = this.clinicService.findOwnerByLastName(lastName);
118	        } else {
119	            owners = this.clinicService.findAllOwners();
120	        }
121	        if (owners.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
130	        Owner owner = this.clinicService.findOwnerById(ownerId);
131	        if (owner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
143	        if (owner.getRegistrationDate() == null) {
144	            owner.setRegistrationDate(LocalDate.now());
145	        }
146	        if (isDailyRegistrationLimitReached()) {
147	            throw new DailyOwnerRegistrationLimitException(
148	                "The maximum of " + MAX_OWNERS_PER_DAY
149	                    + " owners that may be registered today has already been reached");
150	        }
151	        if (isDuplicateTelephone(owner)) {
152	            throw new DuplicateOwnerException("An owner with telephone "
153	                + owner.getTelephone() + " already exists");
154	        }
155	        if (isDuplicateEmail(owner)) {
156	            throw new DuplicateOwnerException("An owner with email "
157	                + owner.getEmail() + " already exists");
158	        }
159	        if (isCityOwnerLimitReached(owner.getCity())) {
160	            throw new CityOwnerLimitException("The city " + owner.getCity()
161	                + " already contains the maximum of " + MAX_OWNERS_PER_CITY + " owners");
162	        }
163	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
164	        owner.setMembershipNumber(membershipNumber);
165	        owner.setMembershipTier(membershipNumber <= FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD");
166	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
167	        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
168	        owner.setLocality(resolveLocality(owner.getCity()));
169	        owner.setCity(resolveCity(owner.getCity()));
170	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
171	        this.clinicService.saveOwner(owner);
172	        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
173	            currentUsername(), owner.getId(), owner.getMembershipNumber());
174	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
175	        headers.setLocation(UriComponentsBuilder.newInstance()
176	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
177	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    /**
181	     * Determines whether the maximum number of owner registrations permitted for today has
182	     * already been reached. Owners are counted by registration date, comparing against the
183	     * current day, so the limit resets at midnight.
184	     *
185	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_DAY} owners already carry today's
186	     *         registration date
187	     */
188	    private boolean isDailyRegistrationLimitReached() {
189	        LocalDate today = LocalDate.now();
190	        long registeredToday = this.clinicService.findAllOwners().stream()
191	            .filter(existing -> today.equals(existing.getRegistrationDate()))
192	            .count();
193	        return registeredToday >= MAX_OWNERS_PER_DAY;
194	    }
195	
196	    /**
197	     * Determines whether the given city already contains the maximum number of owners permitted
198	     * per city. Owners are counted by matching their city ignoring letter case. A {@code null}
199	     * city is never considered to have reached the limit.
200	     *
201	     * @param city the city of the owner about to be created
202	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_CITY} owners already reside in the
203	     *         given city
204	     */
205	    private boolean isCityOwnerLimitReached(String city) {
206	        if (city == null) {
207	            return false;
208	        }
209	        long ownersInCity = this.clinicService.findAllOwners().stream()
210	            .filter(existing -> existing.getCity() != null
211	                && existing.getCity().equalsIgnoreCase(city))
212	            .count();
213	        return ownersInCity >= MAX_OWNERS_PER_CITY;
214	    }
215	
216	    /**
217	     * Determines whether any other owner already uses the candidate's telephone number.
218	     * The comparison ignores letter case and surrounding or repeated whitespace.
219	     *
220	     * @param candidate the owner about to be created
221	     * @return {@code true} if an owner with the same telephone is already present in the data store
222	     */
223	    private boolean isDuplicateTelephone(Owner candidate) {
224	        String telephone = normalizeTelephone(candidate.getTelephone());
225	        return this.clinicService.findAllOwners().stream()
226	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
227	    }
228	
229	    /**
230	     * Canonicalises a telephone number by stripping every character that is not a digit
231	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
232	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
233	     * an owner and used for the telephone-uniqueness check.
234	     *
235	     * @param telephone the raw telephone value, possibly {@code null}
236	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
237	     */
238	    private static String normalizeTelephone(String telephone) {
239	        if (telephone == null) {
240	            return null;
241	        }
242	        return telephone.replaceAll("[^0-9]", "");
243	    }
244	
245	    /**
246	     * Determines whether any other owner already uses the candidate's email address.
247	     * An absent or blank email is never considered a duplicate. The comparison ignores
248	     * letter case and surrounding or repeated whitespace.
249	     *
250	     * @param candidate the owner about to be created
251	     * @return {@code true} if an owner with the same email is already present in the data store
252	     */
253	    private boolean isDuplicateEmail(Owner candidate) {
254	        String email = normalize(candidate.getEmail());
255	        if (email == null || email.isBlank()) {
256	            return false;
257	        }
258	        return this.clinicService.findAllOwners().stream()
259	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
260	    }
261	
262	    /**
263	     * Builds the customer code for a newly created owner, formatted as
264	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
265	     * owners already present in the same city, zero-padded to four digits
266	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
267	     *
268	     * @param city the city of the owner about to be created
269	     * @return the formatted customer code
270	     */
271	    /**
272	     * Resolves the city name to store for a newly created owner. The supplied city is
273	     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
274	     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
275	     * However, if an owner already exists in that city (matched ignoring letter case), that
276	     * existing owner's exact spelling of the city is reused instead, so a single canonical
277	     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
278	     * rather than being flattened to {@code "Mcfarland"}).
279	     *
280	     * @param city the raw city supplied for the owner about to be created
281	     * @return the existing owner's spelling if the city is already known, otherwise the
282	     *         title-cased city; {@code null} if {@code city} was {@code null}
283	     */
284	    private String resolveCity(String city) {
285	        if (city == null) {
286	            return null;
287	        }
288	        return this.clinicService.findAllOwners().stream()
289	            .map(Owner::getCity)
290	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
291	            .findFirst()
292	            .orElseGet(() -> titleCase(city));
293	    }
294	
295	    /**
296	     * Converts a city name to title case: each whitespace-separated word has its first letter
297	     * upper-cased and its remaining letters lower-cased, while the original whitespace is left
298	     * untouched. For example {@code "san   FRANCISCO"} becomes {@code "San   Francisco"}.
299	     *
300	     * @param city the city to title-case
301	     * @return the title-cased city
302	     */
303	    private static String titleCase(String city) {
304	        StringBuilder result = new StringBuilder(city.length());
305	        boolean startOfWord = true;
306	        for (int i = 0; i < city.length(); i++) {
307	            char c = city.charAt(i);
308	            if (Character.isWhitespace(c)) {
309	                startOfWord = true;
310	                result.append(c);
311	            } else if (startOfWord) {
312	                result.append(Character.toTitleCase(c));
313	                startOfWord = false;
314	            } else {
315	                result.append(Character.toLowerCase(c));
316	            }
317	        }
318	        return result.toString();
319	    }
320	
321	    /**
322	     * Counts how many owners already present in the data store share the given last name,
323	     * ignoring letter case. This is evaluated before the new owner is saved, so it reflects
324	     * the number of <em>other</em> owners carrying that last name at creation time.
325	     *
326	     * @param lastName the last name of the owner about to be created
327	     * @return the number of existing owners with the same last name; {@code 0} if the last
328	     *         name is {@code null}
329	     */
330	    private int countNamesakes(String lastName) {
331	        if (lastName == null) {
332	            return 0;
333	        }
334	        return (int) this.clinicService.findAllOwners().stream()
335	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
336	            .count();
337	    }
338	
339	    /**
340	     * Determines whether another owner already resides at the same address and city as the owner
341	     * about to be created. Both address and city are matched ignoring letter case. This is
342	     * evaluated before the new owner is saved, so it reflects only owners that already existed.
343	     *
344	     * @param address the address of the owner about to be created
345	     * @param city    the city of the owner about to be created
346	     * @return {@code true} if an existing owner already has the same address and city
347	     */
348	    /**
349	     * Determines the locality of the owner about to be created relative to the existing clientele.
350	     * The result is {@code "local"} if the owner's city is the single most common city among all
351	     * owners that already exist, and {@code "remote"} otherwise. Cities are grouped ignoring letter
352	     * case. If there are no existing owners, or if two or more cities are tied for the most common
353	     * (so there is no single most common city), the result is {@code "remote"}.
354	     *
355	     * @param city the city of the owner about to be created
356	     * @return {@code "local"} if the city is the single most common among existing owners,
357	     *         otherwise {@code "remote"}
358	     */
359	    private String resolveLocality(String city) {
360	        if (city == null) {
361	            return "remote";
362	        }
363	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
364	            .map(Owner::getCity)
365	            .filter(Objects::nonNull)
366	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(Locale.ROOT),
367	                Collectors.counting()));
368	        long maxCount = countsByCity.values().stream()
369	            .mapToLong(Long::longValue)
370	            .max()
371	            .orElse(0L);
372	        if (maxCount == 0L) {
373	            return "remote";
374	        }
375	        List<String> mostCommonCities = countsByCity.entrySet().stream()
376	            .filter(entry -> entry.getValue() == maxCount)
377	            .map(Map.Entry::getKey)
378	            .toList();
379	        if (mostCommonCities.size() != 1) {
380	            return "remote";
381	        }
382	        return mostCommonCities.get(0).equals(city.toLowerCase(Locale.ROOT)) ? "local" : "remote";
383	    }
384	
385	    private boolean sharesHousehold(String address, String city) {
386	        if (address == null || city == null) {
387	            return false;
388	        }
389	        return this.clinicService.findAllOwners().stream()
390	            .anyMatch(existing -> address.equalsIgnoreCase(existing.getAddress())
391	                && city.equalsIgnoreCase(existing.getCity()));
392	    }
393	
394	    private String nextCustomerCode(String city) {
395	        long ownersInCity = this.clinicService.findAllOwners().stream()
396	            .filter(existing -> existing.getCity() != null
397	                && existing.getCity().equalsIgnoreCase(city))
398	            .count();
399	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
400	    }
401	
402	    /**
403	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
404	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
405	     * any run of internal whitespace is collapsed to a single space, and the result is
406	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
407	     * normalise to {@code "john smith"}.
408	     *
409	     * @param value the raw value, possibly {@code null}
410	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
411	     */
412	    private static String normalize(String value) {
413	        if (value == null) {
414	            return null;
415	        }
416	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
417	    }
418	
419	    /**
420	     * Resolves the name of the currently authenticated user for audit logging.
421	     *
422	     * @return the authenticated user's name, or {@code "anonymous"} if there is no authentication
423	     */
424	    private static String currentUsername() {
425	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
426	        if (authentication == null || authentication.getName() == null) {
427	            return "anonymous";
428	        }
429	        return authentication.getName();
430	    }
431	
432	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
433	    @Override
434	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
435	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
436	        if (currentOwner == null) {
437	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
438	        }
439	        currentOwner.setAddress(ownerFieldsDto.getAddress());
440	        currentOwner.setCity(ownerFieldsDto.getCity());
441	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
442	        currentOwner.setLastName(ownerFieldsDto.getLastName());
443	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
444	        this.clinicService.saveOwner(currentOwner);
445	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Transactional
450	    @Override
451	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
452	        Owner owner = this.clinicService.findOwnerById(ownerId);
453	        if (owner == null) {
454	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
455	        }
456	        this.clinicService.deleteOwner(owner);
457	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
458	    }
459	
460	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
461	    @Override
462	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
463	        Owner owner = this.clinicService.findOwnerById(ownerId);
464	        if (owner == null) {
465	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
466	        }
467	        HttpHeaders headers = new HttpHeaders();
468	        Pet pet = petMapper.toPet(petFieldsDto);
469	        owner.setId(ownerId);
470	        pet.setOwner(owner);
471	        pet.getType().setName(null);
472	        this.clinicService.savePet(pet);
473	        PetDto petDto = petMapper.toPetDto(pet);
474	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
475	            .buildAndExpand(pet.getId()).toUri());
476	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
477	    }
478	
479	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
480	    @Override
481	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
482	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
483	        if (currentOwner != null) {
484	            Pet currentPet = this.clinicService.findPetById(petId);
485	            if (currentPet != null) {
486	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
487	                currentPet.setName(petFieldsDto.getName());
488	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
489	                this.clinicService.savePet(currentPet);
490	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
491	            }
492	        }
493	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
494	    }
495	
496	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
497	    @Override
498	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
499	        HttpHeaders headers = new HttpHeaders();
500	        Visit visit = visitMapper.toVisit(visitFieldsDto);
501	        Pet pet = new Pet();
502	        pet.setId(petId);
503	        visit.setPet(pet);
504	        this.clinicService.saveVisit(visit);
505	        VisitDto visitDto = visitMapper.toVisitDto(visit);
506	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
507	            .buildAndExpand(visit.getId()).toUri());
508	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
509	    }
510	
511	
512	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
513	    @Override
514	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
515	        Owner owner = this.clinicService.findOwnerById(ownerId);
516	        if (owner != null) {
517	            Pet pet = owner.getPet(petId);
518	            if (pet != null) {
519	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
520	            }
521	        }
522	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
523	    }
524	}
