11	/** cp20: WARN to AUDIT when a new owner's area code (first 3 digits) is shared by 5+ existing owners. */
12	@Tag("cp20")
13	class Cp20Tests extends AcceptanceBase {
14	
15		private void createWithAreaCode(String area) throws Exception {
16			ObjectNode o = ownerNode();
17			o.put("telephone", String.format(area + "%07d", seq())); // unique 10-digit, shared 3-digit area
18			createOwnerOk(o);
19		}
20	
21		@Test
