package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.LocalDate;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.mapper.PetMapper;
import org.springframework.samples.petclinic.mapper.VisitMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.Visit;
import org.springframework.samples.petclinic.rest.advice.CityOwnerLimitException;
import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /**
     * Dedicated audit logger recording successful owner creations, including the authenticated
     * user and the new owner's id and membership number.
     */
    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /**
     * The maximum number of owners that may be registered on any single day (by registration date).
     * Once this many owners already carry today's registration date, further creation is rejected.
     */
    private static final int MAX_OWNERS_PER_DAY = 20;

    /**
     * The maximum number of owners permitted in any single city. Once a city already contains
     * this many owners, creating a further owner in that city is rejected. Cities are matched
     * ignoring letter case.
     */
    private static final int MAX_OWNERS_PER_CITY = 8;

    /**
     * The number of owners, counted from the very first ever created, that receive the
     * {@code FOUNDING} membership tier. Owners created once this many already exist receive
     * the {@code STANDARD} tier instead.
     */
    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;

    /**
     * The number of existing owners that must already share a new owner's telephone area code
     * (the first three digits) before the creation is flagged, via a WARN to the AUDIT logger,
     * as a possible bulk signup.
     */
    private static final int BULK_AREA_CODE_THRESHOLD = 5;

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        if (isDailyRegistrationLimitReached()) {
            throw new DailyOwnerRegistrationLimitException(
                "The maximum of " + MAX_OWNERS_PER_DAY
                    + " owners that may be registered today has already been reached");
        }
        if (isDuplicateTelephone(owner)) {
            throw new DuplicateOwnerException("An owner with telephone "
                + owner.getTelephone() + " already exists");
        }
        if (isDuplicateEmail(owner)) {
            throw new DuplicateOwnerException("An owner with email "
                + owner.getEmail() + " already exists");
        }
        if (isCityOwnerLimitReached(owner.getCity())) {
            throw new CityOwnerLimitException("The city " + owner.getCity()
                + " already contains the maximum of " + MAX_OWNERS_PER_CITY + " owners");
        }
        boolean bulkAreaCodeSignup = isBulkAreaCodeSignup(owner.getTelephone());
        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
        owner.setMembershipNumber(membershipNumber);
        owner.setMembershipTier(membershipNumber <= FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD");
        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
        owner.setLocality(resolveLocality(owner.getCity()));
        owner.setCity(resolveCity(owner.getCity()));
        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
        this.clinicService.saveOwner(owner);
        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
            currentUsername(), owner.getId(), owner.getMembershipNumber());
        if (bulkAreaCodeSignup) {
            AUDIT.warn("Possible bulk signup: owner ownerId={} shares telephone area code {} "
                    + "with {} or more existing owners",
                owner.getId(), areaCode(owner.getTelephone()), BULK_AREA_CODE_THRESHOLD);
        }
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    /**
     * Determines whether the maximum number of owner registrations permitted for today has
     * already been reached. Owners are counted by registration date, comparing against the
     * current day, so the limit resets at midnight.
     *
     * @return {@code true} if at least {@link #MAX_OWNERS_PER_DAY} owners already carry today's
     *         registration date
     */
    private boolean isDailyRegistrationLimitReached() {
        LocalDate today = LocalDate.now();
        long registeredToday = this.clinicService.findAllOwners().stream()
            .filter(existing -> today.equals(existing.getRegistrationDate()))
            .count();
        return registeredToday >= MAX_OWNERS_PER_DAY;
    }

    /**
     * Determines whether the given city already contains the maximum number of owners permitted
     * per city. Owners are counted by matching their city ignoring letter case. A {@code null}
     * city is never considered to have reached the limit.
     *
     * @param city the city of the owner about to be created
     * @return {@code true} if at least {@link #MAX_OWNERS_PER_CITY} owners already reside in the
     *         given city
     */
    private boolean isCityOwnerLimitReached(String city) {
        if (city == null) {
            return false;
        }
        long ownersInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> existing.getCity() != null
                && existing.getCity().equalsIgnoreCase(city))
            .count();
        return ownersInCity >= MAX_OWNERS_PER_CITY;
    }

    /**
     * Determines whether any other owner already uses the candidate's telephone number.
     * The comparison ignores letter case and surrounding or repeated whitespace.
     *
     * @param candidate the owner about to be created
     * @return {@code true} if an owner with the same telephone is already present in the data store
     */
    private boolean isDuplicateTelephone(Owner candidate) {
        String telephone = normalizeTelephone(candidate.getTelephone());
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
    }

    /**
     * Canonicalises a telephone number by stripping every character that is not a digit
     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
     * {@code "6135550100"} are treated as the same number. This is the form persisted for
     * an owner and used for the telephone-uniqueness check.
     *
     * @param telephone the raw telephone value, possibly {@code null}
     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
     */
    private static String normalizeTelephone(String telephone) {
        if (telephone == null) {
            return null;
        }
        return telephone.replaceAll("[^0-9]", "");
    }

    /**
     * Determines whether any other owner already uses the candidate's email address.
     * An absent or blank email is never considered a duplicate. The comparison ignores
     * letter case and surrounding or repeated whitespace.
     *
     * @param candidate the owner about to be created
     * @return {@code true} if an owner with the same email is already present in the data store
     */
    private boolean isDuplicateEmail(Owner candidate) {
        String email = normalize(candidate.getEmail());
        if (email == null || email.isBlank()) {
            return false;
        }
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
    }

    /**
     * Builds the customer code for a newly created owner, formatted as
     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
     * owners already present in the same city, zero-padded to four digits
     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
     *
     * @param city the city of the owner about to be created
     * @return the formatted customer code
     */
    /**
     * Resolves the city name to store for a newly created owner. The supplied city is
     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
     * However, if an owner already exists in that city (matched ignoring letter case), that
     * existing owner's exact spelling of the city is reused instead, so a single canonical
     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
     * rather than being flattened to {@code "Mcfarland"}).
     *
     * @param city the raw city supplied for the owner about to be created
     * @return the existing owner's spelling if the city is already known, otherwise the
     *         title-cased city; {@code null} if {@code city} was {@code null}
     */
    private String resolveCity(String city) {
        if (city == null) {
            return null;
        }
        return this.clinicService.findAllOwners().stream()
            .map(Owner::getCity)
            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
            .findFirst()
            .orElseGet(() -> titleCase(city));
    }

    /**
     * Converts a city name to title case: each whitespace-separated word has its first letter
     * upper-cased and its remaining letters lower-cased, while the original whitespace is left
     * untouched. For example {@code "san   FRANCISCO"} becomes {@code "San   Francisco"}.
     *
     * @param city the city to title-case
     * @return the title-cased city
     */
    private static String titleCase(String city) {
        StringBuilder result = new StringBuilder(city.length());
        boolean startOfWord = true;
        for (int i = 0; i < city.length(); i++) {
            char c = city.charAt(i);
            if (Character.isWhitespace(c)) {
                startOfWord = true;
                result.append(c);
            } else if (startOfWord) {
                result.append(Character.toTitleCase(c));
                startOfWord = false;
            } else {
                result.append(Character.toLowerCase(c));
            }
        }
        return result.toString();
    }

    /**
     * Counts how many owners already present in the data store share the given last name,
     * ignoring letter case. This is evaluated before the new owner is saved, so it reflects
     * the number of <em>other</em> owners carrying that last name at creation time.
     *
     * @param lastName the last name of the owner about to be created
     * @return the number of existing owners with the same last name; {@code 0} if the last
     *         name is {@code null}
     */
    private int countNamesakes(String lastName) {
        if (lastName == null) {
            return 0;
        }
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
            .count();
    }

    /**
     * Determines whether another owner already resides at the same address and city as the owner
     * about to be created. Both address and city are matched ignoring letter case. This is
     * evaluated before the new owner is saved, so it reflects only owners that already existed.
     *
     * @param address the address of the owner about to be created
     * @param city    the city of the owner about to be created
     * @return {@code true} if an existing owner already has the same address and city
     */
    /**
     * Determines the locality of the owner about to be created relative to the existing clientele.
     * The result is {@code "local"} if the owner's city is the single most common city among all
     * owners that already exist, and {@code "remote"} otherwise. Cities are grouped ignoring letter
     * case. If there are no existing owners, or if two or more cities are tied for the most common
     * (so there is no single most common city), the result is {@code "remote"}.
     *
     * @param city the city of the owner about to be created
     * @return {@code "local"} if the city is the single most common among existing owners,
     *         otherwise {@code "remote"}
     */
    private String resolveLocality(String city) {
        if (city == null) {
            return "remote";
        }
        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
            .map(Owner::getCity)
            .filter(Objects::nonNull)
            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(Locale.ROOT),
                Collectors.counting()));
        long maxCount = countsByCity.values().stream()
            .mapToLong(Long::longValue)
            .max()
            .orElse(0L);
        if (maxCount == 0L) {
            return "remote";
        }
        List<String> mostCommonCities = countsByCity.entrySet().stream()
            .filter(entry -> entry.getValue() == maxCount)
            .map(Map.Entry::getKey)
            .toList();
        if (mostCommonCities.size() != 1) {
            return "remote";
        }
        return mostCommonCities.get(0).equals(city.toLowerCase(Locale.ROOT)) ? "local" : "remote";
    }

    private boolean sharesHousehold(String address, String city) {
        if (address == null || city == null) {
            return false;
        }
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> address.equalsIgnoreCase(existing.getAddress())
                && city.equalsIgnoreCase(existing.getCity()));
    }

    private String nextCustomerCode(String city) {
        long ownersInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> existing.getCity() != null
                && existing.getCity().equalsIgnoreCase(city))
            .count();
        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
    }

    /**
     * Canonicalises a value for duplicate detection so that comparisons ignore letter
     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
     * any run of internal whitespace is collapsed to a single space, and the result is
     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
     * normalise to {@code "john smith"}.
     *
     * @param value the raw value, possibly {@code null}
     * @return the normalised value, or {@code null} if {@code value} was {@code null}
     */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * Resolves the name of the currently authenticated user for audit logging.
     *
     * @return the authenticated user's name, or {@code "anonymous"} if there is no authentication
     */
    private static String currentUsername() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication == null || authentication.getName() == null) {
            return "anonymous";
        }
        return authentication.getName();
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }
}
